import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;

public class TestUtils {
    public static String encode(String input) {
        return Jsoup.encode(input, "UTF-8").replaceAll("%3D", "=");
    }

    public static void testEncodeEncodeDecodeTest() {
        String url = "http://example.com/path?param=value";
        Document document = Jsoup.parse(url);
        String encoded = encode(document.text());
        System.out.println(encoded);

        String decodedUrl = decode(encoded);
        if (decodedUrl.isEmpty()) {
            throw new RuntimeException("Decode failed");
        }
    }

    public static void testEncodeTest() {
        String url = "http://example.com/path?param=value";
        String encoded = encode(url);
        System.out.println(encoded);
        System.out.println(TestUtils.decode(encoded));
    }

    public static void testDecodeTest() {
        String url = "http://example.com/path?param=value";
        String encoded = encode(url);
        System.out.println(encoded);
        String decodedUrl = decode(encoded);
        if (decodedUrl.isEmpty()) {
            throw new RuntimeException("Decode failed");
        }
    }

    public static void testEncodeNoneTest() {
        String url = "http://example.com/path?param=value";
        String encoded = encode(url);
        System.out.println(encoded);
        assert false;
    }
}

class Main {
    public static void main(String[] args) {
        new TestUtils().testEncodeEncodeDecodeTest();
        new TestUtils().testEncodeTest();
        new TestUtils().testDecodeTest();
    }
}
